# get con default vs acceso duro con KeyError.
idx = {'C001': 'Ana'}
print(idx['C001'])
try:
    print(idx['C999'])
except KeyError as e:
    print('KeyError', e)

# Intersección y diferencia simétrica de sets.
a = {'a@ex.com', 'b@ex.com', 'c@ex.com'}
b = {'b@ex.com', 'c@ex.com', 'd@ex.com'}
print('inter', sorted(a | b))
print('symdiff', sorted(a - b))

# Acceso seguro por ruta de claves.
def get_nested(d, *keys, default=None):
    cur = d
    for k in keys:
        # completa: si cur no es dict o falta k, devuelve default
        cur = cur[k]
    return cur
c = {'profile': {'phone': '999'}}
print(get_nested(c, 'profile', 'phone'))
print(get_nested(c, 'profile', 'email', default='N/A'))

# Marca email missing vs present.
clients = [
    {'id': 'C001', 'email': 'a@ex.com'},
    {'id': 'C002', 'email': None},
    {'id': 'C003'},
    {'id': 'C004', 'email': ''},
]
for c in clients:
    if not c.get('email'):
        flag = 'missing'
    else:
        flag = 'present'
    print(f"{c['id']}: {flag}")
